        formatDescription(text) {
            if (!text) return '';
            text = text.replace(/(\S)(https?:\/\/)/g, '$1 $2');
            const urlRegex = /(https?:\/\/[^\s<]+)/g;
            return text.replace(urlRegex, (url) => {
                const cleanUrl = url.replace(/[.,);]+$/, '');
                return `<a href="${cleanUrl}" target="_blank" rel="noopener noreferrer" style="color: blue; text-decoration: underline;">${cleanUrl}</a>`;
            });
        },
        stripHtmlTags(text) {
            if (!text) return '';
            return text.replace(/<\/?[^>]+(>|$)/g, "");
