        FetchMemberListing: async function () {
            var ths = this;
            var url = `id=${ths.ProjectId}&moduleName=&type=USERLISTINE_FOR_COMMENT&search=&refId=`;
            await DataService.GetDDLData(url).then((response) => {
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.data.DATA.length > 0) {
                            response.data.DATA.map((element) => {
                                var obj = {
                                    value: element.value,
                                    name: element.name
                                }
                                ths.filteredMentionUsers.push(obj)
                            })
                        }
                    }
                }
            })

        },
        handleMentionKeydown(event) {
            if (this.showMentionDropdown) {
                const filteredUsers = this.filteredMentionUsers;
                if (event.key === 'ArrowDown') {
                    event.preventDefault();
                    this.selectedMentionIndex = Math.min(this.selectedMentionIndex + 1, filteredUsers.length - 1);
                } else if (event.key === 'ArrowUp') {
                    event.preventDefault();
                    this.selectedMentionIndex = Math.max(this.selectedMentionIndex - 1, 0);
                } else if (event.key === 'Enter') {
                    event.preventDefault();
                    event.stopPropagation();
                } else if (event.key === 'Tab') {
                    event.preventDefault();
                } else if (event.key === 'Escape') {
                    event.preventDefault();
                    this.showMentionDropdown = false;
                } else {
                    this.$nextTick(() => {
                        this.handleMentionInput(event);
                    });
                }
                return;
            }
            if (event.key === '@') {
                this.$nextTick(() => {
                    this.handleMentionInput(event);
                });
            }
        },
        handleMentionInput(event) {
            this.mentionText = '';
            this.mentionText = event.key;
            if (this.mentionText.includes('@')) {
                this.showMentionDropdown = true;
            } else {
                this.showMentionDropdown = false;
            }
        },
