        SaveTask: async function () {
            var vm = this;
            if (vm.isDetailEditable) {
                await this.$refs.dynamicform.validateForm.validate().then((result) => {
                    if (result) {
                        var checkTotalWeightage = 0;
                        var TaskName = vm.FormSchema[0].Data[0].value;
                        var TaskType = vm.FormSchema[0].Data[1].value;
                        var StartDate = vm.FormSchema[0].Data[2].value;
                        var EndtDate = vm.FormSchema[0].Data[3].value;
                        var Status = vm.FormSchema[0].Data[4].value;
                        var Sprint = vm.FormSchema[0].Data[7].value == '' ? 0 : vm.FormSchema[0].Data[7].value;
                        var Priority = vm.FormSchema[0].Data[8].value;
                        var weightage = vm.FormSchema[0].Data[12].value;
                        var Component = vm.FormSchema[0].Data[13].value;
                        var Environment = vm.FormSchema[0].Data[14].value;
                        var oldWeightage = vm.projectdata != null ? vm.projectdata.weightage : 0;
                        checkTotalWeightage = vm.projectdata != null ? vm.projectdata.TotalWeightage : 0;
                        checkTotalWeightage -= parseInt(oldWeightage);
                        checkTotalWeightage += parseInt(weightage);
                        if (checkTotalWeightage > 100 && vm.IndustryType_Name == 'Construction') {
                            vm.ShowAlert(vm.$t('TotalWeightageRange'), "failure", true, vm.$t("Alert"));
                            return;
                        }
                        if (StartDate && EndtDate) {
                            const start = new Date(StartDate);
                            const end = new Date(EndtDate);
                            start.setHours(0, 0, 0, 0);
                            end.setHours(0, 0, 0, 0);
                            if (start > end) {
                                vm.ShowAlert(vm.$t('Enddatecannot'), "failure", true, vm.$t("Alert"));
                                return;
                            }
                        }
                        var stage_id = vm.FormSchema[0].Data[9].value;
                        var Hours = vm.Hours;
                        var Description = vm.Descriptionn;
                        var obj = {
                            TaskId: vm.projectdata != null ? vm.projectdata.task_id : 0,
                            Project_id: vm.ProjectId,
                            TaskName: TaskName,
                            StartDate: StartDate,
                            Stageid: stage_id,
                            EndDate: EndtDate,
                            SprintId: Sprint,
                            PriorityId: Priority,
                            StatusId: Status,
                            UserId: vm.Users,
                            BackLogDescription: Description,
                            EHours: Hours,
                            Weightage: weightage,
                            TASK_TYPE: TaskType,
                            ComponentId: parseInt(Component),
                            EnvironmentId: parseInt(Environment)

                        }
                        var globalhours = vm.getTotalHoursBetweenDates(vm.gloabStartDate, vm.gloabEndDate)
                        var hoursbetweendate = vm.getTotalHoursBetweenDates(obj.StartDate, obj.EndDate)
                        if (parseFloat(hoursbetweendate) > parseFloat(globalhours)) {
                            vm.isLoading = false;
                            vm.ShowAlert([vm.$t("tasktotalhours"), vm.$t(vm.ProjectTotalHours)], "failure", vm.$t('Alert'));
                            return;
                        }
                        var objectPostString = JSON.stringify(obj);
                        DataService.UpdateTask(objectPostString).then(function (response) {
                            vm.isLoading = false;
                            // vm.isDetailEditable = false;
                            if (response && response.data.status == "Success") {
                                if (response.data.result == 'INVALID_WEIGHTAGE') {
                                    vm.ShowAlert(vm.$t('Subtask weightage cannot be greater than the parent tasks weightage.', [vm.$t(vm.NewTabName)]), "failure", true, vm.$t("Alert"));
                                    return;
                                }
                                else if (response.data.result == 'insert') {
                                    vm.ShowAlert(vm.$t('AddedSuccess', [vm.$t(vm.NewTabName)]), "success", true, vm.$t("Alert"));
                                    vm.CloseTask();
                                    return;
                                }
                                else if (response.data.result == 'Update') {
                                    vm.ShowAlert(vm.$t('UpdatedSuccess', [vm.$t(vm.NewTabName)]), "success", true, vm.$t("Alert"));
                                }
                                else if (response.data.result == 'EXIST') {
                                    vm.ShowAlert(vm.$t('AlreadyExists', [vm.$t('Task')]), "warning", true, vm.$t("Alert"));
                                }

                                if (vm.projectdata.parent_task_id == 0) {
                                    vm.UpdateTaskDetails();
                                }
                                else {
                                    vm.GetSubTaskDetails(vm.projectdata.task_id, vm.projectdata.parent_task_id);
                                    vm.UpdateTaskDetails();
                                }
                                vm.$emit('callbackfunction', obj);

                            } else {
                                vm.ShowAlert(vm.$t("UnknownErrorOccur"), "failure", true, vm.$t('Alert'));
                            }

                        })
                    }
                })
            }


        },
        previewFiles(event) {
            const file = event.target.files && event.target.files[0];
            this.selectedFile = file || null;
            this.getFileName = file ? file.name : '';
            this.contentType = {
                "ContentType": file ? file.type : null,
                "Size": file ? file.size : null,
                "Extension": file ? file.name.substring(file.name.lastIndexOf('.')) : null
            }
        },
        async uploadToDocStorage(file) {
            const vm = this;
            const formData = new FormData();
            formData.append("fileId", vm.FileId || 0);
            formData.append("folderId", 0);
            formData.append("moduleName", "ProjectFiles");
            formData.append("subModuleName", "");
            formData.append("isGlobal", 0);
            formData.append("file", file);
            formData.append("contentType", file.type);
            const response = await DataService.UploadStreamNew(formData);
            const newdata = response && response.data ? response.data : null;
            if (!newdata) {
                throw new Error("Empty response from DocStorage upload");
            }
            if (newdata.UploadStatus !== 1) {
                throw new Error(newdata.ErrorMsg || "DocStorage upload failed");
            }
            return newdata;
        },
        SaveFile: async function () {
            var vm = this;
            if (vm.selectedFile == null) {
                vm.ShowAlert(vm.$t('Selectatleastonefile'), "failure", true, vm.$t("Alert"));
                return;
            }
            if (vm.selectedFile == null) {
                vm.ShowAlert(vm.$t('Selectatleastonefile'), "failure", true, vm.$t("Alert"));
                return;
            }
            vm.isLoading = true;
            if (vm.selectedFile) {
                var uploadedInfo = await vm.uploadToDocStorage(vm.selectedFile);
                if (uploadedInfo) {
                    var fileUrl = uploadedInfo.FilePath;
                    var FileName = uploadedInfo.FileName;
                    var FileThumb = uploadedInfo.FileThumbPath;
                    const formData = new FormData();
                    var VarObject = {
                        FileTitle: '',
                        FileName: FileName,
                        Description: vm.FormSchemaa[0].Data[1].value,
                        FilePath: fileUrl,
                        ProjectId: vm.projectdata.project_id,
                        TaskId: vm.projectdata.task_id,
                        UserIds: vm.Users,
                        FileId: 0,
                        ContentType: vm.contentType,
                        FileThumb: FileThumb
                    }
                    formData.append("postString", JSON.stringify(VarObject));
                    await DataService.SaveTeamMember(formData).then((response) => {
                        if (response.data == 1) {
                            vm.isLoading = false;
                            vm.GetFilesListing();
                            vm.isShowUploadFile = false;
                            vm.selectedFile = null
                            vm.FormSchemaa[0].Data[1].value = '';
                            vm.ShowAlert("File Added Successfully!", "success", true, vm.$t("Alert"));
                            let payload = {
                                projectId: vm.ProjectId,
                                projectName: 'text',
                                projectContent: `${VarObject.UserIds} ${vm.$t('uploaded')} ${VarObject.FileTitle}`,
                            };
                            DataService.SendAddProjectNotification(JSON.stringify(payload)).then((res) => {
                               
                            });
                            if (vm.Screen == 'Files') {
                                vm.$emit('GetFilesListing');
                                vm.$parent.IsFileUploadModalShow = false;
                                vm.$parent.IsNewVersionUpload = false;
                            }
                            else {
                                vm.$emit('GetFilesListing');
                                vm.$parent.IsFileUploadModalShow = false;
                                vm.$parent.IsNewVersionUpload = false;
                            }
                        }
                        else if (response.data == 3) {
                            vm.ShowAlert("FileAlreadyExists", "warning", true, vm.$t("Alert"));
                        }
                    });
                }
            }
        },
        UploadFile: async function (evt) {
            try {
                var vm = this;
                vm.fileData = [];
                for (var i = 0; i < evt.length; i++) {
                    vm.file = evt[i];
                }
                const formData = new FormData();
                formData.append('file', vm.file);
                await DataService.UploadImageFile(formData).then(response => {
                    if (response.data.status == "1") {
                        vm.filePath = response.data.filePath;
                    }
                }).catch(err => {
                   
                })
            }
            catch (ex) {
                console.error("Error processing attachments:", ex);
            }
        },
        GetSubTaskDetails: async function (task_id, parent_task_id) {
            var vm = this;
            var url = `SprintId=${parent_task_id}&Type=SubTask&ProjectId=${vm.projectdata.project_id}`;
